let draftDirty=false, draftConflict=null, draftRevision=0, autoSaveTimer=null, cloudSavePromise=null, cloudRefreshPromise=null, cloudGeneration=0, lastSyncedAt=null, cloudSyncError=null, routeAutoJoin=false, cloudScope=null, hasCloudSnapshot=false, draftPendingCreate=false, legacyDraftUnreviewed=hasLocalDraft;
try{const meta=JSON.parse(localStorage.getItem(draftMetaKey));if(meta?.id===s.id){draftDirty=meta?.dirty===true;draftPendingCreate=meta?.pendingCreate===true;legacyDraftUnreviewed=false;}}catch{}
let result=calculateScenario(s);
