const get=(path)=>path.split('.').reduce((o,k)=>o?.[k],s);
const set=(path,value)=>{const a=path.split('.');const k=a.pop();let o=s;for(let i=0;i<a.length;i++){if(!o[a[i]]||typeof o[a[i]]!=='object')o[a[i]]=/^\d+$/.test(a[i+1]||k)?[]:{};o=o[a[i]];}o[k]=value};
function persist(){try{localStorage.setItem(draftKey,JSON.stringify(s));localStorage.setItem(draftMetaKey,JSON.stringify({id:s.id||null,dirty:draftDirty,pendingCreate:draftPendingCreate}));hasLocalDraft=true}catch{toast('No se pudo conservar el borrador. Exporta una copia.')}}
function scheduleDraftSave(){if(autoSaveTimer)window.clearTimeout?.(autoSaveTimer);if(window.setTimeout&&((draftDirty&&s.id&&!draftConflict)||profileDirty)&&cloud?.householdId)autoSaveTimer=window.setTimeout(()=>{autoSaveTimer=null;void syncDraft().catch(error=>{toast(error.message);render();});},800);}
function markDraftChanged(){draftDirty=true;draftRevision++;persist();scheduleDraftSave();}
function profileKey(){return 'casa-ideal.family-budget.v1:'+(cloud?.householdId?cloud.url+'|'+cloud.householdId:'local');}
function persistFamilyProfile(){try{localStorage.setItem(profileKey(),JSON.stringify({profile:familyProfile,dirty:profileDirty}));}catch{cloudSyncError='No se pudo conservar el presupuesto familiar en este dispositivo.';}}
function receiveFamilyProfile(rows,scopeChanged){
 const remote=rows.find(isFamilyProfile)||null;
 if(scopeChanged){familyProfile=null;profileDirty=false;profileConflict=false;try{const cached=JSON.parse(localStorage.getItem(profileKey()));if(isFamilyProfile(cached?.profile)&&cached.dirty){familyProfile=cached.profile;profileDirty=true;}}catch{}}
 if(profileDirty){if((remote?.updatedAt||null)!==(familyProfile?.updatedAt||null))profileConflict=true;}
 else{familyProfile=remote;profileConflict=false;}
 if(familyProfile&&!draftDirty&&!legacyDraftUnreviewed)s=withProfile(s);
 persistFamilyProfile();
}
async function syncFamilyProfile(){
 if(profileSavePromise)return profileSavePromise;
 if(!profileDirty||!familyProfile)return;
 if(profileConflict)throw Error('El presupuesto familiar ha cambiado en otro dispositivo. Revisa la versión familiar antes de guardar.');
 if(!cloud?.householdId){profileDirty=false;persistFamilyProfile();return;}
 const candidate=copy(familyProfile),encoded=JSON.stringify(candidate);cloudGeneration++;
 const test=calculateScenario(applyFamilyProfile(DEFAULT_SCENARIO,candidate));
 if(!test.valid)throw Error('Revisa el presupuesto familiar: '+test.validation.errors.join(' '));
 profileSavePromise=(async()=>{try{
  const saved=await cloud.save(candidate,{create:!candidate.updatedAt,expectedUpdatedAt:candidate.updatedAt});
  cloudRows=[...cloudRows.filter(x=>x.id!==FAMILY_PROFILE_ID),saved];cloudSyncError=null;connectionState='connected';lastSyncedAt=new Date();
  if(JSON.stringify(familyProfile)===encoded){familyProfile=saved;profileDirty=false;}else{familyProfile.updatedAt=saved.updatedAt;familyProfile.createdAt=saved.createdAt;}
  profileConflict=false;persistFamilyProfile();localStore.reconcileCloud(cloudRows,{scope:`${cloud.url}|${cloud.householdId}`});
 }catch(error){cloudSyncError=error.message;if(error.code==='SCENARIO_CONFLICT')profileConflict=true;error.familyProfile=true;persistFamilyProfile();throw error;}finally{profileSavePromise=null;cloudGeneration++;if(profileDirty&&!profileConflict&&!cloudSyncError)scheduleDraftSave();}})();
 return profileSavePromise;
}
async function toggleFavorite(id){
 await flushDraft();const home=(cloud?.householdId?cloudRows:localStore.getScenarios()).find(x=>x.id===id&&!isFamilyProfile(x));if(!home)throw Error('La vivienda ya no está en la lista.');
 cloudGeneration++;let saved;try{if(cloud?.householdId){saved=await cloud.save({...home,favorite:!home.favorite},{create:false,expectedUpdatedAt:cloudRows.find(x=>x.id===id)?.updatedAt});cloudRows=[...cloudRows.filter(x=>x.id!==id),saved];localStore.reconcileCloud(cloudRows,{scope:`${cloud.url}|${cloud.householdId}`});}else saved=localStore.saveScenario({...home,favorite:!home.favorite});
 if(s.id===id){s=withProfile(saved);persist();}render();}finally{cloudGeneration++;}
}
function sameScenarioContent(a,b){const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).filter(k=>!['updatedAt','createdAt'].includes(k)).sort().map(k=>[k,stable(v[k])])):v;return JSON.stringify(stable(normalizeScenario(a)))===JSON.stringify(stable(normalizeScenario(b)));}
function applyCloudSnapshot(rows){
 const scope=`${cloud.url}|${cloud.householdId}`,scopeChanged=scope!==cloudScope,previous=!scopeChanged?cloudRows:[];cloudScope=scope;receiveFamilyProfile(rows,scopeChanged);cloudRows=rows;hasCloudSnapshot=true;connectionState='connected';cloudSyncError=null;lastSyncedAt=new Date();
 localStore.reconcileCloud(rows,{scope:`${cloud.url}|${cloud.householdId}`,knownIds:previous.map(x=>x.id)});
 selected=new Set([...selected].filter(id=>rows.some(x=>x.id===id)));
 if(s.id){const remote=rows.find(x=>x.id===s.id);if(!remote){if(!draftPendingCreate)draftConflict='deleted';}else{if(legacyDraftUnreviewed){if(!sameScenarioContent(s,remote)){draftDirty=true;draftConflict='changed';}else{s.updatedAt=remote.updatedAt;}legacyDraftUnreviewed=false;persist();}if(remote.updatedAt!==s.updatedAt){if(draftDirty||document.activeElement?.matches?.('#view input, #view select, #view textarea')||document.querySelector('dialog[open]'))draftConflict='changed';else{s=withProfile(copy(remote));draftConflict=null;persist();}}}}
}
async function refreshFamily({quiet=true}={}){
 if(!cloud?.householdId||savingHousing||cloudSavePromise||profileSavePromise)return;
 if(cloudRefreshPromise)return cloudRefreshPromise;
 const generation=cloudGeneration;
 cloudRefreshPromise=(async()=>{try{const rows=await cloud.list();if(generation!==cloudGeneration)return;applyCloudSnapshot(rows);if(currentView==='viviendas'||currentView==='familia'||((!draftDirty||draftConflict||profileConflict)&&!document.querySelector('dialog[open]')&&!document.querySelector('#view input:focus, #view select:focus, #view textarea:focus')))render();if(!quiet)toast('Lista familiar actualizada.');}catch(error){cloudSyncError=error.message;connectionState='offline';if(!quiet)toast('Sincronización pendiente: '+error.message);if(currentView==='viviendas'||currentView==='familia')render();}})().finally(()=>{cloudRefreshPromise=null;});
 return cloudRefreshPromise;
}
async function syncDraft(){
 if(cloudSavePromise)return cloudSavePromise;
 if(!draftDirty||!s.id||!cloud?.householdId||draftConflict)return syncFamilyProfile();
 if(!hasCloudSnapshot){await refreshFamily();if(!hasCloudSnapshot||draftConflict)return;}
 if(!draftPendingCreate&&!cloudRows.some(x=>x.id===s.id)){draftConflict='deleted';render();return;}
 const candidate=withProfile(copy(s)),revision=draftRevision;if(!calculateScenario(candidate).valid||!validateCommute(candidate.commute).valid){cloudSyncError='Revisa los campos incompletos o inválidos antes de sincronizar.';return;}cloudGeneration++;
 cloudSavePromise=(async()=>{try{const saved=await cloud.save(candidate,{create:draftPendingCreate,expectedUpdatedAt:candidate.updatedAt});cloudRows=[...cloudRows.filter(x=>x.id!==saved.id),saved];localStore.reconcileCloud(cloudRows,{scope:`${cloud.url}|${cloud.householdId}`});lastSyncedAt=new Date();cloudSyncError=null;connectionState='connected';draftPendingCreate=false;if(s.id===saved.id){if(draftRevision===revision){s=withProfile(saved);draftDirty=false;}else{s.updatedAt=saved.updatedAt;s.createdAt=saved.createdAt;}persist();}await syncFamilyProfile();if(!document.querySelector('#view input:focus, #view select:focus, #view textarea:focus'))render();}catch(error){cloudSyncError=error.message;if(error.familyProfile){}else if(error.code==='SCENARIO_CONFLICT')draftConflict='changed';else connectionState='offline';persist();render();toast('Los cambios siguen en este dispositivo. '+error.message);}finally{cloudGeneration++;cloudSavePromise=null;if(draftDirty&&!draftConflict&&!cloudSyncError)scheduleDraftSave();}})();return cloudSavePromise;
}
async function flushDraft({switching=false}={}){
 if(autoSaveTimer){window.clearTimeout?.(autoSaveTimer);autoSaveTimer=null;}
 if(cloudSavePromise)await cloudSavePromise;
 if(draftDirty&&s.id&&cloud?.householdId&&!draftConflict)await syncDraft();
 if(profileDirty)await syncFamilyProfile();
 if(draftDirty&&(switching||s.id&&cloud?.householdId))throw Error('El borrador tiene cambios pendientes. Corrígelos o revisa la sincronización antes de abrir otra vivienda; tus datos se conservan.');
}
function syncNotice(){
 if(!cloud?.householdId)return '';
 if(profileConflict)return notice('<strong>El presupuesto familiar ha cambiado en otro dispositivo.</strong> Conservamos tus cambios sin sustituir los de tu familia. <button class="card-link" data-action="use-family-budget">Abrir presupuesto de la familia</button> <button class="card-link" data-action="export">Exportar mi copia antes</button>','error');
 if(draftConflict&&currentView!=='viviendas')return notice(`<strong>${draftConflict==='deleted'?'Esta vivienda no está en la lista familiar actual.':'Esta vivienda ha cambiado en otro dispositivo.'}</strong> Conservamos tu borrador y no sustituiremos los cambios de tu familia.<div class="inline-actions">${draftConflict==='changed'?'<button class="button secondary" data-action="use-family-version">Abrir versión familiar</button>':''}<button class="button secondary" data-action="draft-as-new">Conservar como vivienda nueva</button><button class="button plain" data-view="viviendas">Ver lista actual</button></div>`,'error');
 return notice(`<strong>${cloudSyncError?'Sincronización pendiente.':draftDirty||profileDirty?'Guardando cambios…':'Familia sincronizada.'}</strong> ${cloudSyncError?'El borrador está conservado en este dispositivo.':''}${lastSyncedAt?` <span class="sync-time">Última consulta: ${lastSyncedAt.toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}.</span>`:''} <button class="card-link" data-action="refresh-cloud">Actualizar ahora</button>`,'info');
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function field(label,path,{hint='',suffix='€',nullable=false,min=0,max,step='any',scale=1,type='number'}={}){const v=get(path);return `<label>${label}${suffix?` <span class="muted">(${suffix})</span>`:''}<input data-field="${path}" data-scale="${scale}" ${nullable?'data-nullable="true"':''} type="${type}" ${type==='number'?`min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}"`:''} value="${v==null?'':esc(typeof v==='number'?+(v*scale).toFixed(6):v)}" ${nullable?'placeholder="Pendiente"':''}>${hint?`<span class="field-hint">${hint}</span>`:''}</label>`}
function check(label,path,hint=''){return `<label class="check-label"><input type="checkbox" data-field="${path}" ${get(path)?'checked':''}><span>${label}${hint?`<span class="field-hint">${hint}</span>`:''}</span></label>`}
function select(label,path,options,hint=''){return `<label>${label}<select data-field="${path}" ${typeof get(path)==='number'?'data-number="true"':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(get(path))===String(v)?'selected':''}>${l}</option>`).join('')}</select>${hint?`<span class="field-hint">${hint}</span>`:''}</label>`}
const row=(label,value,extra='')=>`<div class="line-item ${extra}"><span>${label}</span><strong>${value}</strong></div>`;
function notice(text,cls=''){return `<div class="notice ${cls}">${text}</div>`}
function section(title,subtitle,body){return `<section class="card form-section"><div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div></div>${body}</section>`}
function warningSummary(){const pending=result.budget?.incomplete,estimated=(result.budget?.propertyCostsEstimated||result.budget?.assumedLoanTerms);return `<div class="notice ${pending?'':'info'}"><strong>${estimated?'Presupuesto orientativo con provisiones o hipótesis de préstamo.':pending?'Todavía faltan datos para decidir.':'Estimación completa con los datos introducidos.'}</strong> ${estimated?'Los recibos reales pueden ser superiores o inferiores. Completa también las cuotas y primas que falten.':pending?'Las cifras mensuales son el mínimo conocido; completa ingresos, primas y gastos.':'Revisa presupuestos y condiciones antes de comprometer la compra.'}${result.budget?.missingQuotes?.length?`<br>Pendiente: ${esc(result.budget.missingQuotes.join(', '))}.`:''}</div>`}
function resultSidebar(){if(!result.valid)return '';return `<aside class="side-stack sticky"><section class="card side-card"><div class="mini-label">TU SIMULACIÓN AHORA</div><div class="budget-number">${(result.budget.propertyCostsEstimated||result.budget.assumedLoanTerms)?'≈ ':result.budget.incomplete?'≥ ':''}${euro(result.budget.totalMonthly)}<span class="muted" style="font-size:11px;font-weight:400"> /mes</span></div><p>Presupuesto total familiar ${(result.budget.propertyCostsEstimated||result.budget.assumedLoanTerms)?'· orientativo':result.budget.incomplete?'· mínimo conocido':''}</p><div class="breakdown">${row('Solo hipoteca',euro(result.mortgage.monthlyPayment,2))}${row('Préstamo bancario de mamá',euro(result.familyLoan.monthlyPayment,2))}${row('Casa + suministros',euro(result.budget.homeMonthly,2))}${row('Dinero para comprar',euro(result.cash.totalRequired))}${row('Falta por cubrir',euro(result.cash.fundingGap),'total')}</div>${warningSummary()}</section></aside>`}
